/// How an operand is published (see visit()).
enum class OperandKind : uint8_t
{
    SCALAR, ///< `<name>`: a scalar attribute
    TENSOR, ///< `<role>.<field>`: a tensor reference
    TENSORS, ///< `<role>[i].<field>`: a vector of tensor references, of any length
    ELEMENTS, ///< `<name>[i]`: a vector attribute, whose length the schema leaves open
};

struct OperandEntry
{
    std::string_view nodeType;
    std::string_view name;
    OperandKind kind;
    /// Whether a valid node of the type may leave the operand out.
    bool optional;
};

